/* Engagement content extracted from tcf_giving_portal_merged_v13.html */
var GARDEN_BADGES=[{"id":"volunteer","plant":"Black-Eyed Susan","desc":"Volunteer Locally","colors":["var(--tcf-aqua)","var(--tcf-orange)","var(--tcf-primary)"],"verify":"selfreport","howto":"Spend time volunteering at any organization in the city this month, then tell us where. This one’s on the honor system — no proof needed.","fieldLabel":"Organization name","placeholder":"e.g. Ohio City Farm, Boys & Girls Club…","story":"Black-Eyed Susans are one of the first wildflowers to take root in overlooked, disturbed ground — vacant lots, roadsides, the corners of the city everyone else drives past. We paired it with volunteering because showing up for the parts of Cleveland that need it most is exactly what this flower already does on its own. [Swap in the real Land Floral story for Black-Eyed Susan.]"},{"id":"event","plant":"Elm","desc":"Attend an Event","colors":["var(--tcf-blue)","var(--tcf-primary)","var(--tcf-aqua)"],"verify":"selfreport","howto":"Go to a festival, open house, town hall, block party, or school board meeting — anything where the community gathers. Tell us what you attended.","fieldLabel":"Event name","placeholder":"e.g. West Side Market Block Party…","story":"American elms once arched over Cleveland’s main streets and town squares — the shade neighbors gathered under. It’s a natural match for showing up wherever the community comes together. [Swap in the real Land Floral story for Elm.]"},{"id":"gift","plant":"Oak","desc":"Make a Gift","colors":["var(--tcf-orange)","var(--tcf-mid-green)","var(--tcf-orange)"],"verify":"auto","howto":"Make a gift of any amount, anywhere on the platform. This badge unlocks automatically — nothing else to do.","story":"Mighty oaks grow from little acorns. A gift of any size, given time, becomes something lasting — the same idea behind every fund at the Cleveland Foundation. [Swap in the real Land Floral story for Oak.]"},{"id":"why","plant":"Foxglove","desc":"Share Your Why","colors":["var(--tcf-orange)","var(--tcf-pink)","var(--tcf-primary)"],"verify":"post","howto":"Post a short reflection on what moved you to get involved in your community. It’ll appear on the Stories &amp; Impact feed.","fieldLabel":"Your why","placeholder":"Share a short reflection…","story":"Foxglove has long been tied to matters of the heart. We paired it with sharing your “why” because that’s the most personal, heart-driven check-in of the six. [Swap in the real Land Floral story for Foxglove.]"},{"id":"refer","plant":"Milkweed","desc":"Refer a Friend","colors":["var(--tcf-orange)","var(--tcf-aqua)","var(--tcf-primary)"],"verify":"share","howto":"Use the share button below to invite a friend. We’ll unlock this as soon as the share sheet opens.","story":"Milkweed is the one plant monarch butterflies depend on at every stop of their migration — without it, the journey can’t continue. Referring a friend makes you that same kind of waypoint for someone else’s giving journey. [Swap in the real Land Floral story for Milkweed.]"},{"id":"localbiz","plant":"Walnut","desc":"Support Local Business","colors":["var(--tcf-aqua)","var(--tcf-primary)","var(--tcf-orange)"],"verify":"selfreport","howto":"Shop or grab a bite at a locally owned business in the city this month, then tell us where.","fieldLabel":"Business name","placeholder":"e.g. Rising Star Coffee, East 66th…","story":"Walnut trees quietly shape everything that grows around them, and their wood has always been prized in local craft — it felt right for supporting the small businesses that anchor Cleveland’s neighborhoods. [Swap in the real Land Floral story for Walnut.]"}];
var LEGENDS=[{"id":1,"name":"Frederick Harris Goff","years":"1858–1923","cat":"Business & Philanthropy","color":"green","quote":"Why not pool the good will of an entire city into one enduring trust?","story":"In 1914, banker and lawyer Frederick Goff had a radical idea: instead of letting charitable dollars sit locked in outdated wills, why not pool them into one flexible, permanent trust guided by the living community? That idea became the Cleveland Foundation — the world's first community foundation — a model now used by more than 1,700 community foundations across the globe.","legacy":"Every gift to the Cleveland Foundation today carries forward the trust Fred Goff built more than a century ago."},{"id":2,"name":"John D. Rockefeller","years":"1839–1937","cat":"Business & Philanthropy","color":"green","quote":"Cleveland made me. Standard Oil made Cleveland.","story":"Rockefeller built Standard Oil on Cleveland's docks and rail lines starting in 1870, turning a modest lake port into an industrial powerhouse that employed generations of families. The fortune he built here also seeded a lifelong practice of large-scale philanthropy that became a model for American giving.","legacy":"His giving helped establish the idea that great wealth carries a great responsibility to the community that made it possible."},{"id":3,"name":"Amasa Stone","years":"1818–1883","cat":"Business & Philanthropy","color":"green","quote":"A railroad man who built more than bridges.","story":"A railroad and bridge-building magnate, Amasa Stone's fortune funded the move of Case School of Applied Science and Western Reserve's Adelbert College to Cleveland — planting the seeds of what is now University Circle, still the city's hub of education, medicine, and culture.","legacy":"One gift, made a century and a half ago, is still educating Clevelanders today."},{"id":4,"name":"Charles F. Brush","years":"1849–1929","cat":"Business & Science","color":"aqua","quote":"Lighting a city, one arc lamp at a time.","story":"In 1879, Brush lit Cleveland's Public Square with his own arc-light invention, making it one of the first electrically lit cities in the world. His engineering company later became part of General Electric, and his estate helped fund scientific research in Cleveland for decades.","legacy":"A single invention changed how an entire city lived after dark — and his estate kept giving long after."},{"id":5,"name":"Garrett A. Morgan","years":"1877–1963","cat":"Business & Invention","color":"orange","quote":"An inventor who also built a community.","story":"A Black inventor and entrepreneur, Morgan patented the three-position traffic signal and a safety hood that became a forerunner of the modern gas mask — using it himself to help rescue trapped workers after a 1916 tunnel explosion. He built a successful business while becoming an early leader of Cleveland's Black community.","legacy":"His inventions still shape every intersection you drive through today."},{"id":6,"name":"Cyrus Eaton","years":"1883–1979","cat":"Business & Philanthropy","color":"green","quote":"A Cleveland fortune, spent on world peace.","story":"A self-made Cleveland financier, Eaton used his industrial fortune to fund the Pugwash Conferences, bringing scientists together across Cold War lines to push for nuclear disarmament — proof that a Cleveland businessman's generosity could shape world peace.","legacy":"His giving reached far beyond Cleveland, all the way to the world stage."},{"id":7,"name":"Peter B. Lewis","years":"1933–2013","cat":"Business & Philanthropy","color":"green","quote":"Betting big on his hometown's culture.","story":"Lewis built Progressive Insurance into a national leader, then became one of Cleveland's boldest philanthropists — reshaping the Cleveland Museum of Art and betting big on the city's cultural future with transformative gifts most donors wouldn't dare make.","legacy":"His gifts prove that ambitious giving can change a skyline, not just a balance sheet."},{"id":8,"name":"Morton L. Mandel","years":"1921–2019","cat":"Business & Philanthropy","color":"green","quote":"Three brothers, one lasting commitment.","story":"With brothers Jack and Joseph, Mandel built Premier Industrial into a national company — then poured that success into the Mandel Foundation, becoming one of the most consistent and far-reaching philanthropic forces in Cleveland's history.","legacy":"A family business became a family legacy of giving that still shapes Cleveland today."},{"id":9,"name":"Jeptha H. Wade","years":"1811–1890","cat":"Business & Philanthropy","color":"green","quote":"One gift of land, enjoyed by generations.","story":"A founder of Western Union, Wade's gift of land created Wade Park — today home to the Cleveland Museum of Art and Cleveland Botanical Garden — turning one family's generosity into a permanent gift for every Clevelander.","legacy":"Millions of visits later, his single gift is still giving."},{"id":10,"name":"Dan Gilbert","years":"b. 1962","cat":"Business & Philanthropy","color":"orange","quote":"Betting his fortune on downtown's comeback.","story":"The founder of Rocket Companies poured hundreds of millions of dollars into rebuilding downtown Cleveland block by block, while co-owning the Cavaliers through their historic 2016 championship — betting his fortune on his hometown's comeback.","legacy":"A downtown skyline, rebuilt one investment at a time."},{"id":11,"name":"Carl B. Stokes","years":"1927–1996","cat":"Civil Rights & Politics","color":"pink","quote":"A seat at the head of the table.","story":"In 1967, Carl Stokes was elected the first Black mayor of a major American city — a milestone that reshaped what was possible in urban politics nationwide, and gave Cleveland's Black community a seat at the head of the table.","legacy":"A city hall door, opened for the first time, that has stayed open ever since."},{"id":12,"name":"Louis Stokes","years":"1925–2015","cat":"Civil Rights & Politics","color":"pink","quote":"Fifteen terms, one relentless purpose.","story":"Ohio's first Black member of Congress, Louis Stokes spent 15 terms fighting for civil rights, healthcare access, and fair representation — carrying his brother Carl's legacy of public service to Washington for nearly three decades.","legacy":"Decades of service, still felt in the policies that protect Clevelanders today."},{"id":13,"name":"Jane Edna Hunter","years":"1882–1971","cat":"Civil Rights & Social Work","color":"pink","quote":"A safe place to land, and a chance to rise.","story":"Arriving in Cleveland with almost nothing, Hunter founded the Phillis Wheatley Association to give Black women migrating north safe housing, job training, and a community — a lifeline that helped shape generations of Cleveland families.","legacy":"An institution built from nothing, still lifting people up today."},{"id":14,"name":"Charles W. Chesnutt","years":"1858–1932","cat":"Civil Rights & Literature","color":"pink","quote":"A lawyer by day, a truth-teller by night.","story":"A Cleveland lawyer by day, Chesnutt became one of the first commercially successful African American novelists, using fiction to confront America's racial injustices at a time when few publishers would take the risk.","legacy":"Stories that took a real risk to tell — and are still read for their honesty today."},{"id":15,"name":"John Malvin","years":"1795–1880","cat":"Civil Rights","color":"pink","quote":"Fighting for freedoms decades before they were won.","story":"An early Cleveland abolitionist, Malvin organized against slavery and fought for Black Ohioans' right to education and citizenship decades before the Civil War — laying groundwork for the civil rights movement that would follow a century later.","legacy":"A fight for justice that started generations before it was won."},{"id":16,"name":"Lucy Stanton Day Sessions","years":"1831–1910","cat":"Civil Rights & Education","color":"pink","quote":"Education and activism, hand in hand.","story":"Believed to be the first Black woman to complete a four-year college course, Stanton returned to Cleveland to teach, organize, and advocate — proving that education and activism could go hand in hand.","legacy":"A first that opened the door for every student who followed."},{"id":17,"name":"William O. Walker","years":"1896–1981","cat":"Civil Rights & Journalism","color":"pink","quote":"A press that gave a community its voice.","story":"As editor of the Call & Post for decades, Walker used the press to build Black political power in Cleveland, holding leaders accountable and giving voice to a community too often overlooked by the city's other papers.","legacy":"Decades of reporting that made sure Cleveland's Black community was heard."},{"id":18,"name":"Eliza Bryant","years":"1827–1907","cat":"Civil Rights & Social Work","color":"pink","quote":"Dignity, for those the city too often forgot.","story":"Bryant founded what became the Eliza Bryant Center, one of the nation's oldest homes for elderly African Americans — ensuring that Cleveland's Black elders would be cared for with dignity when few institutions would take them in.","legacy":"A home she built is still caring for Cleveland's elders today."},{"id":19,"name":"Fannie Lewis","years":"1926–2008","cat":"Civil Rights & Politics","color":"pink","quote":"Rebuilding a neighborhood, block by block.","story":"Cleveland's longest-serving female City Council member, Lewis fought fiercely for the Hough neighborhood's revival after decades of disinvestment, proving that one determined advocate could rebuild a community block by block.","legacy":"Proof that showing up, decade after decade, changes a neighborhood for good."},{"id":20,"name":"Stephanie Tubbs Jones","years":"1949–2008","cat":"Civil Rights & Politics","color":"pink","quote":"A relentless focus on the people she served.","story":"The first Black woman elected to Congress from Ohio, Tubbs Jones represented Cleveland with a relentless focus on healthcare, education, and civil rights until her sudden passing in office.","legacy":"A first that reshaped who gets to represent Cleveland in Washington."},{"id":21,"name":"Tom L. Johnson","years":"1854–1911","cat":"Politics","color":"blue","quote":"The best-governed city in America.","story":"As mayor from 1901 to 1909, Johnson took on Cleveland's streetcar monopolies and pushed for fair taxation and public ownership of utilities — reforms so effective that muckraker Lincoln Steffens called him \"the best mayor of the best-governed city in America.\"","legacy":"Reforms from a century ago that still shape how Cleveland runs its own utilities."},{"id":22,"name":"Newton D. Baker","years":"1871–1937","cat":"Politics","color":"blue","quote":"A reformer's spirit, carried to Washington.","story":"A reform-minded Cleveland mayor, Baker went on to serve as U.S. Secretary of War during World War I, carrying the city's progressive spirit onto the national stage during one of the country's most consequential moments.","legacy":"A hometown reformer who helped lead the country through a world war."},{"id":23,"name":"James A. Garfield","years":"1831–1881","cat":"Politics","color":"blue","quote":"From a canal-boat driver to the presidency.","story":"Raised and educated in the Western Reserve, Garfield rose from a canal-boat driver to the 20th President of the United States — a Northeast Ohio story of ambition and public service cut short by an assassin's bullet.","legacy":"A reminder that this region has always produced people who reach for more."},{"id":24,"name":"George V. Voinovich","years":"1936–2016","cat":"Politics","color":"blue","quote":"Restoring a city's credit — and its confidence.","story":"Elected mayor as Cleveland teetered near a second financial default, Voinovich helped restore the city's credit and confidence — a turnaround that launched him to the governorship and U.S. Senate.","legacy":"A financial comeback that gave Cleveland its footing back."},{"id":25,"name":"Dennis Kucinich","years":"b. 1946","cat":"Politics","color":"blue","quote":"Refusing to sell what belonged to the people.","story":"At 31, Kucinich became Cleveland's youngest big-city mayor, famously refusing to sell the city's public power system even at great political cost — a decision now credited with saving Clevelanders money for generations.","legacy":"A stand that still saves Cleveland households money on their electric bill."},{"id":26,"name":"Michael R. White","years":"b. 1951","cat":"Politics","color":"blue","quote":"Twelve years, one rebuilt downtown.","story":"Over twelve years as mayor, White drove a wave of downtown redevelopment — including the Gateway sports and entertainment district — reshaping Cleveland's skyline and its sense of possibility.","legacy":"A downtown many Clevelanders now take for granted, built on his watch."},{"id":27,"name":"Florence Ellinwood Allen","years":"1884–1966","cat":"Civil Rights & Law","color":"pink","quote":"Breaking a barrier that had stood for the nation's entire history.","story":"A leading voice for women's suffrage, Allen went on to become the first woman to serve as chief judge of a U.S. federal appeals court — breaking barriers in law that had stood for the nation's entire history.","legacy":"A first on the bench that opened the door for every woman judge who followed."},{"id":28,"name":"Frank Lausche","years":"1895–1990","cat":"Politics","color":"blue","quote":"Decades of trust, earned one term at a time.","story":"Rising from Cleveland mayor to Ohio governor and U.S. senator, Lausche's decades of public trust made him one of the most enduring political figures Ohio has ever produced.","legacy":"Trust built over decades, from City Hall to the U.S. Senate."},{"id":29,"name":"George Washington Crile","years":"1864–1943","cat":"Medicine","color":"aqua","quote":"A transfusion that changed what surgery could survive.","story":"A co-founder of the Cleveland Clinic, Crile performed one of the world's first successful direct blood transfusions and pioneered treatments for surgical shock — discoveries that would go on to save countless lives far beyond Cleveland.","legacy":"A discovery made in Cleveland that still saves lives in operating rooms everywhere."},{"id":30,"name":"Harvey Cushing","years":"1869–1939","cat":"Medicine","color":"aqua","quote":"The father of modern neurosurgery.","story":"Born and trained in Cleveland, Cushing is widely regarded as the father of modern neurosurgery, developing techniques still used in operating rooms around the world today.","legacy":"Surgical techniques from a Cleveland-trained mind, still used worldwide."},{"id":31,"name":"Donald A. Glaser","years":"1926–2013","cat":"Science","color":"aqua","quote":"A tool that let scientists see the invisible.","story":"A Cleveland-born physicist, Glaser won the Nobel Prize for inventing the bubble chamber — a tool that let scientists literally see subatomic particles for the first time, unlocking decades of physics discovery.","legacy":"A Cleveland idea that helped physicists see the building blocks of everything."},{"id":32,"name":"Frederick C. Robbins","years":"1916–2003","cat":"Medicine","color":"aqua","quote":"A breakthrough that helped end a disease families feared.","story":"Working at Case Western Reserve, Robbins helped grow poliovirus in tissue culture — a Nobel Prize-winning breakthrough that made the polio vaccine possible and helped end a disease that once terrified American families.","legacy":"Research done here helped free a generation of children from fear."},{"id":33,"name":"Jim Lovell","years":"b. 1928","cat":"Science & Exploration","color":"aqua","quote":"A safe return that became a legend.","story":"Born in Cleveland, Lovell commanded NASA's Apollo 13 mission, whose crew's safe return from a near-catastrophic accident became one of the most celebrated feats in the history of American spaceflight.","legacy":"A Cleveland-born commander who brought his crew home against the odds."},{"id":34,"name":"Albert A. Michelson & Edward W. Morley","years":"1852–1931 / 1838–1923","cat":"Science","color":"aqua","quote":"An experiment that pointed toward relativity.","story":"In 1887, working at what's now Case Western Reserve, these two scientists ran the famous Michelson-Morley experiment — a result so unexpected it helped point the way toward Einstein's theory of relativity.","legacy":"A surprising result from a Cleveland lab that helped rewrite modern physics."},{"id":35,"name":"Langston Hughes","years":"1901–1967","cat":"Literature","color":"orange","quote":"A voice found in a Cleveland classroom.","story":"Hughes found his voice as a writer while attending Cleveland's Central High School, going on to become one of the defining poets of the Harlem Renaissance and American literature.","legacy":"A poet's voice, first found here, that still speaks to readers everywhere."},{"id":36,"name":"Harvey Pekar","years":"1939–2010","cat":"Literature & Comics","color":"orange","quote":"The everyday, made extraordinary.","story":"A Cleveland file clerk with no artistic training, Pekar turned the everyday grit of working-class life into \"American Splendor,\" one of the most acclaimed and honest comic series ever created.","legacy":"Proof that Cleveland's ordinary streets held extraordinary stories worth telling."},{"id":37,"name":"Jerry Siegel & Joe Shuster","years":"1914–1996 / 1914–1992","cat":"Comics & Culture","color":"orange","quote":"A hero dreamed up in a Glenville bedroom.","story":"Two Glenville High School classmates dreamed up a hero who could leap tall buildings — and gave the world Superman, launching an entire genre of American storytelling from a bedroom in Cleveland.","legacy":"An entire genre of American storytelling, born from two Cleveland teenagers."},{"id":38,"name":"Dorothy Fuldheim","years":"1893–1989","cat":"Journalism","color":"orange","quote":"Nearly five decades of hard-hitting truth.","story":"Fuldheim became one of the first women in America to anchor a daily televised newscast, delivering hard-hitting commentary from Cleveland for nearly five decades and paving the way for women in broadcast journalism.","legacy":"A door she opened on-air that every woman in broadcast news walked through next."},{"id":39,"name":"Adella Prentiss Hughes","years":"1869–1950","cat":"Arts & Music","color":"orange","quote":"A city that decided it deserved a great orchestra.","story":"Hughes organized the concerts that grew into the Cleveland Orchestra in 1918, founding one of the world's great symphony orchestras and establishing Cleveland as a serious cultural capital.","legacy":"A concert series that grew into a world-class orchestra Clevelanders still fill seats for."},{"id":40,"name":"George Szell","years":"1897–1970","cat":"Music","color":"orange","quote":"Twenty-four years of exacting brilliance.","story":"Over 24 exacting years as music director, Szell built the Cleveland Orchestra's sound and reputation into one of the finest in the world — a legacy still heard in Severance Hall today.","legacy":"A sound he shaped decades ago, still filling Severance Hall today."},{"id":41,"name":"Toni Morrison","years":"1931–2019","cat":"Literature","color":"orange","quote":"A Nobel voice, shaped by this region.","story":"Raised in nearby Lorain and shaped by the Greater Cleveland region, Morrison became the first African American woman to win the Nobel Prize in Literature, writing novels that changed how America understood its own history.","legacy":"A regional upbringing that produced one of literature's most essential voices."},{"id":42,"name":"Bill Watterson","years":"b. 1958","cat":"Comics & Culture","color":"orange","quote":"Walking away rather than compromise the work.","story":"Raised in Chagrin Falls, Watterson created \"Calvin and Hobbes\" — then famously walked away at the height of its fame rather than compromise it, leaving behind one of the most beloved comic strips in American history.","legacy":"A body of work protected on principle, still beloved decades later."},{"id":43,"name":"Alan Freed","years":"1921–1965","cat":"Music & Media","color":"orange","quote":"The night rock and roll got its name.","story":"A Cleveland radio DJ, Freed popularized the phrase \"rock and roll\" and hosted the Moondog Coronation Ball in 1952 — widely considered the first rock concert ever — a legacy that helped bring the Rock &amp; Roll Hall of Fame to Cleveland's shores.","legacy":"A radio show that helped earn Cleveland its place as the home of rock and roll."},{"id":44,"name":"Bob Hope","years":"1903–2003","cat":"Entertainment","color":"orange","quote":"A Cleveland kid who spent his career giving back.","story":"Raised in Cleveland, Hope became one of the 20th century's most beloved entertainers, spending decades of his career performing for American troops around the world.","legacy":"A career spent making people laugh, especially the ones far from home."},{"id":45,"name":"Halle Berry","years":"b. 1966","cat":"Entertainment","color":"orange","quote":"A door in Hollywood, opened for the first time.","story":"Raised in Cleveland, Berry became the first woman of color to win the Academy Award for Best Actress, opening doors in Hollywood that had stayed closed for generations.","legacy":"A first that changed who gets to stand on that stage."},{"id":46,"name":"Paul Newman","years":"1925–2008","cat":"Entertainment & Philanthropy","color":"orange","quote":"Giving away every dollar of profit, on principle.","story":"Born in Shaker Heights, Newman parlayed his Hollywood career into Newman's Own, a food company that gives away 100% of its profits to charity, and co-founded camps that let seriously ill children just be kids.","legacy":"A grocery-aisle idea that has quietly funded charity for decades."},{"id":47,"name":"Bone Thugs-n-Harmony","years":"formed 1990s","cat":"Music","color":"orange","quote":"Putting Cleveland's sound on the map.","story":"This Cleveland hip-hop group pioneered a fast, melodic rap style in the 1990s that influenced a generation of artists — putting the city's sound on the national map.","legacy":"A distinct Cleveland sound that still echoes through hip-hop today."},{"id":48,"name":"Jesse Owens","years":"1913–1980","cat":"Sports","color":"blue","quote":"Four gold medals, one defiant answer.","story":"Training at Cleveland's East Technical High School, Owens went on to win four gold medals at the 1936 Berlin Olympics — a defiant answer to Nazi ideology delivered on the world's biggest stage.","legacy":"A performance on the world's biggest stage that started on a Cleveland track."},{"id":49,"name":"Jim Brown","years":"1936–2023","cat":"Sports & Civil Rights","color":"blue","quote":"Using his platform for more than the game.","story":"Widely considered the greatest running back in NFL history, Brown used his platform as a Cleveland Browns star to become one of the era's most outspoken civil rights and social activists.","legacy":"A legend on the field who used his voice off it, too."},{"id":50,"name":"Larry Doby","years":"1923–2003","cat":"Sports & Civil Rights","color":"blue","quote":"Breaking a barrier with far less recognition.","story":"In 1947, Doby broke the American League's color barrier with the Cleveland Indians, facing down the same hostility Jackie Robinson endured — with far less recognition — to open the game to Black players.","legacy":"A barrier broken in Cleveland that opened the door for every Black player who followed."},{"id":51,"name":"LeBron James","years":"b. 1984","cat":"Sports & Philanthropy","color":"blue","quote":"A championship, then a school.","story":"The Akron-born superstar delivered Cleveland its first major sports championship in 52 years in 2016, then poured his resources into founding the I Promise School, giving struggling Akron-area kids a shot at a better future.","legacy":"A title that ended a 52-year drought — and a school still changing kids' futures."},{"id":52,"name":"Jim Thome","years":"b. 1970","cat":"Sports","color":"blue","quote":"A franchise icon, remembered for his humility.","story":"A Hall of Fame slugger for the Cleveland Indians, Thome became a beloved franchise icon known as much for his humility and community ties as for his towering home runs.","legacy":"A hometown hero whose reputation off the field matched his power on it."}];
var LGD_COLORS={"green":"#164430","orange":"#EE7331","aqua":"#19B9A9","blue":"#1A8DA9","pink":"#C0629A"};
var HIST_QUIZ=[{"idx": 0, "wk": 0, "y": 1914, "cat": "tcf", "diff": "Easy", "q": "In 1914, Cleveland invented a brand-new way for everyday people to give back — one pool of gifts, from many neighbors, that would help the city forever. What was it?", "options": ["America’s first public library", "The country’s first food bank", "The world’s first community foundation", "The first Red Cross chapter"], "correct": 2, "reveal": "Cleveland banker Frederick Goff had a simple idea: a permanent “savings account” for the whole community, so anyone — not just the very rich — could leave something behind for needs no one could predict yet. He called it the Cleveland Foundation. Newspapers across the country wrote about it within weeks, and today communities all over the world have one."}, {"idx": 1, "wk": 1, "y": 1963, "cat": "tcf", "diff": "Easy", "q": "In 1963, Ohio’s first public two-year college got its start in Cleveland. So many people wanted in that the line to apply wrapped around the block. What’s the school called?", "options": ["Cuyahoga Community College (Tri-C)", "Cleveland State University", "Lakeland Community College", "Case Western Reserve University"], "correct": 0, "reveal": "The state law that allowed community colleges didn’t include money to plan one, so the Cleveland Foundation stepped in with early planning grants to help get Tri-C off the ground. More than 900,000 students have walked through its doors since."}, {"idx": 2, "wk": 2, "y": 1973, "cat": "tcf", "diff": "Easy", "q": "In the early 1970s, some of downtown Cleveland’s grand old theaters sat empty and were about to be torn down. What were they going to be replaced with?", "options": ["A highway interchange", "An indoor shopping mall", "A new office tower", "Parking lots"], "correct": 3, "reveal": "Volunteers from the Junior League of Cleveland led a campaign to save them, and the Cleveland Foundation backed the effort starting in 1973. The restored Ohio, Palace and State Theatres grew into Playhouse Square — the largest performing arts center in the country outside New York City."}, {"idx": 3, "wk": 3, "y": 1974, "cat": "sports", "diff": "Easy", "q": "On June 4, 1974, a Cleveland Indians promotion at Municipal Stadium got so far out of hand that umpires forfeited the game to the Texas Rangers. What was the promotion?", "options": ["Free Fireworks Night", "Ten Cent Beer Night", "Nickel Hot Dog Night", "Bat Day"], "correct": 1, "reveal": "Roughly 25,000 people showed up for unlimited 10-cent beers. Fans streamed onto the field in the ninth inning with the game tied, and the Rangers and Indians ended up swinging bats side by side to protect each other. It remains one of the most infamous nights in American sports."}, {"idx": 4, "wk": 4, "y": 1975, "cat": "equity", "diff": "Medium", "q": "Frank Robinson made national history with the Cleveland Indians in April 1975. What did he become?", "options": ["The American League's first designated hitter", "The first player-owner in MLB history", "The first player to manage from the dugout in uniform", "Major League Baseball's first Black manager"], "correct": 3, "reveal": "Robinson was hired as player-manager and homered in his first at-bat on Opening Day at Municipal Stadium. Cleveland broke a color barrier in the manager's office 28 years after Larry Doby broke the American League's playing barrier — also in a Cleveland uniform."}, {"idx": 5, "wk": 5, "y": 1976, "cat": "sports", "diff": "Medium", "q": "The Cavaliers' first playoff run in franchise history, capped by a seven-game series win over the Washington Bullets, is remembered by what nickname?", "options": ["The Miracle of Richfield", "Believeland '76", "The Coliseum Comeback", "The Bicentennial Run"], "correct": 0, "reveal": "The Cavs played in Richfield, about 25 miles south of downtown, and fans rushed the floor after the clincher. Center Jim Chones broke his foot before the conference finals, and Cleveland lost to Boston — a “what if” fans argued about for decades."}, {"idx": 6, "wk": 6, "y": 1977, "cat": "politics", "diff": "Medium", "q": "In 1977 Cleveland elected a 31-year-old mayor — the youngest person to lead a major American city at the time — who was nicknamed “the Boy Mayor.” Who was he?", "options": ["Dennis Kucinich", "Ralph Perk", "George Voinovich", "Michael R. White"], "correct": 0, "reveal": "Kucinich refused to sell the city-owned electric utility, Muny Light, to private interests. That fight helped trigger the events of the following year — and he survived a recall election by fewer than 300 votes."}, {"idx": 7, "wk": 7, "y": 1978, "cat": "politics", "diff": "Medium", "q": "On December 15, 1978, Cleveland became the first major American city since the Great Depression to do what?", "options": ["File for federal bankruptcy protection", "Have its budget taken over by the state", "Dissolve its elected school board", "Default on its financial obligations"], "correct": 3, "reveal": "Note the wording — Cleveland defaulted, it did not declare bankruptcy. The city could not repay roughly $15 million in short-term notes. It took until 1987 to fully climb out, and the stigma shaped how outsiders talked about Cleveland for a generation."}, {"idx": 8, "wk": 8, "y": 1979, "cat": "equity", "diff": "Medium", "q": "On September 10, 1979, Cleveland public schools began what, under an order from U.S. District Judge Frank J. Battisti?", "options": ["Court-ordered crosstown busing to desegregate the schools", "Year-round school calendars", "Open enrollment across district lines", "Mandatory school uniforms"], "correct": 0, "reveal": "Battisti ruled in 1976 that the district had maintained unconstitutional segregation. Cleveland's first day of busing was tense but peaceful, partly because of a multi-year public education campaign funded by more than $1 million from the Cleveland Foundation, plus grassroots groups like WELCOME."}, {"idx": 9, "wk": 9, "y": 1980, "cat": "politics", "diff": "Medium", "q": "Cleveland hosted the only presidential debate of the 1980 campaign, held October 28 at Public Hall. Which two candidates faced off?", "options": ["Jimmy Carter and Ronald Reagan", "Gerald Ford and Jimmy Carter", "Ronald Reagan and Walter Mondale", "George H.W. Bush and Michael Dukakis"], "correct": 0, "reveal": "This is the debate where Reagan asked the country, “Are you better off than you were four years ago?” He won the election a week later. Cleveland's 1980 census also landed that year: the city had fallen to 573,822 people, down from a peak of nearly 915,000 in 1950."}, {"idx": 10, "wk": 10, "y": 1981, "cat": "sports", "diff": "Medium", "q": "On May 15, 1981, Indians pitcher Len Barker did something against the Toronto Blue Jays that has happened fewer than 25 times in MLB history. What was it?", "options": ["Threw a perfect game", "Recorded an unassisted triple play", "Hit for the cycle as a pitcher", "Struck out 20 batters"], "correct": 0, "reveal": "It was a cold, drizzly Friday night and only a few thousand fans were in the stands at Municipal Stadium to see 27 up, 27 down. Cleveland City Council also shrank from 33 members to 21 that year."}, {"idx": 11, "wk": 11, "y": 1982, "cat": "arts", "diff": "Hard", "q": "On June 17, 1982, what Cleveland institution published its final edition, leaving the Plain Dealer as the city's only major daily newspaper?", "options": ["The Cleveland Leader", "The Cleveland Press", "The Cleveland News", "The Call & Post"], "correct": 1, "reveal": "The Press had been a dominant civic voice since 1878, and under longtime editor Louis Seltzer it could make or break a politician. That same year the Cleveland Foundation made the country's first community-foundation program-related investment, buying the Bulkley complex to keep the Playhouse Square restoration alive."}, {"idx": 12, "wk": 12, "y": 1983, "cat": "tcf", "diff": "Medium", "q": "In 1983, the Cleveland Foundation urged City Hall to start planning a public education campaign about a new disease that U.S. health officials had named just a year earlier. What was it?", "options": ["Lead poisoning", "AIDS", "Tuberculosis", "Measles"], "correct": 1, "reveal": "While some cities were slow to respond, the Cleveland Foundation encouraged City Hall to act early and later funded the city’s first AIDS awareness campaign. Cleveland’s approach became the model for a national partnership that helped cities across the country fight the disease."}, {"idx": 13, "wk": 13, "y": 1984, "cat": "tcf", "diff": "Medium", "q": "In 1984 Steven A. Minter became chief executive of the Cleveland Foundation. What made his appointment a national first?", "options": ["He was the first African American to lead a major community foundation in the United States", "He was the first leader recruited from outside Ohio", "He was the first former mayor to lead a foundation", "He was the youngest person ever to lead a major foundation"], "correct": 0, "reveal": "Minter, a Cleveland-area native, had served as the number-two official at the U.S. Department of Education under President Carter. He led the foundation until 2003, through the era that produced Gateway, the Rock Hall, and the neighborhood development system the city still relies on."}, {"idx": 14, "wk": 14, "y": 1985, "cat": "tcf", "diff": "Medium", "q": "By the mid-1980s, Northeast Ohio’s economy had stalled. In 1985 the Cleveland Foundation made a new top priority to help turn things around. What was it?", "options": ["Building a new airport", "Bringing the Olympics to Cleveland", "Creating jobs and helping businesses grow", "Moving City Hall to the lakefront"], "correct": 2, "reveal": "Job and business creation has been a top priority ever since — supporting entrepreneurs, manufacturers and new industries like biotechnology. Fun fact: that same year, a local couple opened the Foundation’s very first fund that let a family recommend its own grants to causes they care about — a way of giving that many families use today."}, {"idx": 15, "wk": 15, "y": 1986, "cat": "arts", "diff": "Easy", "q": "On September 27, 1986, Cleveland set a world record with a United Way fundraiser that went spectacularly sideways. What was released over Public Square?", "options": ["About 1.5 million balloons", "50,000 paper lanterns", "A million rose petals", "10,000 doves"], "correct": 0, "reveal": "Balloonfest '86 looked glorious for about 30 seconds. Then weather pushed the balloons back down over the city and Lake Erie — grounding a runway at Burke Lakefront Airport and hampering a Coast Guard search for two missing boaters. 1986 was also the year Cleveland was chosen as the site of the Rock and Roll Hall of Fame."}, {"idx": 16, "wk": 16, "y": 1987, "cat": "sports", "diff": "Easy", "q": "In the January 1987 AFC Championship Game at Municipal Stadium, which quarterback led a 98-yard march in the closing minutes to tie the game and send it to overtime — a sequence Clevelanders simply call “The Drive”?", "options": ["Jim Kelly", "John Elway", "Boomer Esiason", "Dan Marino"], "correct": 1, "reveal": "Denver won in overtime and went to the Super Bowl. The next January, Earnest Byner fumbled at the Denver goal line in another AFC title game — “The Fumble.” On a brighter note, 1987 was also the year Cleveland finally emerged from default."}, {"idx": 17, "wk": 17, "y": 1988, "cat": "arts", "diff": "Medium", "q": "Which now-legendary band was formed in Cleveland in 1988 by a studio assistant and janitor who recorded his first demos for free during off-hours?", "options": ["The Black Keys", "Nine Inch Nails", "Devo", "Filter"], "correct": 1, "reveal": "Trent Reznor was working at Right Track Studio when owner Bart Koster let him use the room between bookings. Reznor played nearly everything himself. *Pretty Hate Machine* followed in 1989, and NIN became one of the most influential acts of the era."}, {"idx": 18, "wk": 18, "y": 1989, "cat": "politics", "diff": "Medium", "q": "In 1989, Cleveland voters elected Michael R. White in a bruising race against City Council President George Forbes. What was significant about White's tenure?", "options": ["He became Cleveland's second African American mayor and served three terms, the longest run to that point", "He was the first mayor to be recalled", "He was the first mayor who had never held elected office", "He was the first Republican elected mayor since 1941"], "correct": 0, "reveal": "White was a state senator from Glenville when he won. Over 1990–2002 he presided over Gateway, the Rock Hall, the Browns' departure and replacement, and a downtown building boom. Carl Stokes, elected in 1967, had been the first."}, {"idx": 19, "wk": 19, "y": 1990, "cat": "citybuilding", "diff": "Medium", "q": "What downtown project formally opened on March 29, 1990, converting the old rail concourse beneath Terminal Tower into a shopping and entertainment center?", "options": ["The Flats East Bank", "Tower City Center", "The Galleria at Erieview", "The Avenue at Playhouse Square"], "correct": 1, "reveal": "Tower City reopened Public Square as a destination and gave the Rapid a genuine downtown hub. Also in 1990, Cuyahoga County voters approved a “sin tax” on cigarettes and alcohol to finance the Gateway complex."}, {"idx": 20, "wk": 20, "y": 1991, "cat": "citybuilding", "diff": "Medium", "q": "In 1991 a new skyscraper topped off at roughly 948 feet, becoming the tallest building in Ohio — a title it still holds. What is it?", "options": ["Terminal Tower", "The Sherwin-Williams headquarters tower", "200 Public Square (the BP Building)", "Key Tower"], "correct": 3, "reveal": "Designed by César Pelli and originally called Society Center, it was briefly the tallest building between New York and Chicago. Terminal Tower had held the Ohio crown since 1930."}, {"idx": 21, "wk": 21, "y": 1992, "cat": "arts", "diff": "Hard", "q": "In 1992 the Cleveland Orchestra achieved a first for any American orchestra. What was it?", "options": ["It became the first American orchestra to establish a residency at Austria's Salzburg Festival", "It was the first to tour China", "It was the first to broadcast a full season live on television", "It was the first to record a complete Beethoven cycle digitally"], "correct": 0, "reveal": "Under music director Christoph von Dohányi, the orchestra performed regularly at Salzburg from 1990 to 1996 — evidence for the claim that the city punches far above its weight culturally. (The Mark Price–Brad Daugherty–Larry Nance Cavs also won 57 games and reached the Eastern Conference Finals that year.)"}, {"idx": 22, "wk": 22, "y": 1993, "cat": "tcf", "diff": "Easy", "q": "Thanks to one retired dentist’s gift in 1993, people driving into Cleveland on I-71 at night started seeing something new glowing on the skyline. What was it?", "options": ["A giant lighted billboard", "Church steeples, lit up at night", "Floodlit murals in the Flats", "A lighted welcome arch over the highway"], "correct": 1, "reveal": "Dr. Ray Erickson thought the city’s church spires were beautiful and hated that no one could enjoy them after dark. He left his life savings to the Cleveland Foundation to light them up. The “Beacon of Hope” program started in Tremont, and by 2014 seventeen churches were glowing thanks to his gift."}, {"idx": 23, "wk": 23, "y": 1994, "cat": "tcf", "diff": "Medium", "q": "When Cleveland’s new downtown ballpark and arena opened in 1994, the Cleveland Foundation helped pay for something fans walked past on game day. What was it?", "options": ["The ballpark’s scoreboard", "The teams’ new uniforms", "The stadium lights", "The public plazas and outdoor art"], "correct": 3, "reveal": "The Foundation wanted the spaces around the Gateway sports complex to be as exciting as the games. An art competition drew 125 entries, and the winners — like the “Sports Stacks” sculpture and the “Who’s on First?” benches — became instant fan favorites."}, {"idx": 24, "wk": 24, "y": 1995, "cat": "arts", "diff": "Medium", "q": "The Rock and Roll Hall of Fame and Museum opened on Cleveland's lakefront in September 1995. Who designed its glass-pyramid building?", "options": ["Frank Gehry", "Zaha Hadid", "I.M. Pei", "Philip Johnson"], "correct": 2, "reveal": "Cleveland beat out Memphis, New York, and others for the Hall, leaning on DJ Alan Freed's role in popularizing the phrase “rock and roll” and a national call-in poll. 1995 was double-edged: the Indians reached their first World Series since 1954, and in November Art Modell announced he was moving the Browns to Baltimore."}, {"idx": 25, "wk": 25, "y": 1996, "cat": "arts", "diff": "Medium", "q": "Cleveland rap group Bone Thugs-n-Harmony won a Grammy in 1996 for which song?", "options": ["“1st of tha Month”", "“Thuggish Ruggish Bone”", "“Tha Crossroads”", "“Notorious Thugs”"], "correct": 2, "reveal": "The tribute to Eazy-E spent eight weeks at number one on the Billboard Hot 100. The group came out of Cleveland's East Side. 1996 was also Cleveland's bicentennial — and the year the NFL deal was struck that let Cleveland keep the Browns name, colors, and records."}, {"idx": 26, "wk": 26, "y": 1997, "cat": "sports", "diff": "Medium", "q": "The Indians won the American League pennant in 1997 but lost Game 7 of the World Series in extra innings. To whom?", "options": ["Florida Marlins", "Arizona Diamondbacks", "Atlanta Braves", "New York Yankees"], "correct": 0, "reveal": "Cleveland was three outs from a title in the ninth inning of Game 7 in Miami. The Marlins tied it, then won in the 11th. It is still, for a lot of Clevelanders, the one that hurts most."}, {"idx": 27, "wk": 27, "y": 1998, "cat": "equity", "diff": "Medium", "q": "In 1998, Stephanie Tubbs Jones won election to Congress from Ohio's 11th District, succeeding the retiring Louis Stokes. What first did she achieve?", "options": ["First sitting judge elected to Congress from Ohio", "First Cleveland native elected to Congress", "First woman to represent Cuyahoga County", "First African American woman elected to Congress from Ohio"], "correct": 3, "reveal": "A Glenville native and Collinwood High and Case Western Reserve graduate, Tubbs Jones had already been the first African American to serve as Cuyahoga County Prosecutor. She served in Congress until her death in 2008."}, {"idx": 28, "wk": 28, "y": 1999, "cat": "sports", "diff": "Easy", "q": "The expansion Browns returned to the field in September 1999. Where had the original franchise relocated after the 1995 season?", "options": ["Indianapolis", "Houston", "St. Louis", "Baltimore"], "correct": 3, "reveal": "The 1996 settlement was unprecedented: the players and owner went to Baltimore as the Ravens, but the Browns name, colors, and record book legally stayed in Cleveland, held in trust until a new team took the field. The return opener was a 43–0 loss to the Steelers."}, {"idx": 29, "wk": 29, "y": 2000, "cat": "arts", "diff": "Medium", "q": "In January 2000, what Cleveland landmark reopened after a two-year, $36 million restoration and expansion?", "options": ["The Palace Theatre", "The Cleveland Museum of Art", "The main branch of Cleveland Public Library", "Severance Hall"], "correct": 3, "reveal": "Severance, home of the Cleveland Orchestra since 1931, got its Art Deco detailing restored, a new stage shell, and modernized backstage space. Critics promptly re-crowned it one of the most beautiful concert halls in America."}, {"idx": 30, "wk": 30, "y": 2001, "cat": "politics", "diff": "Medium", "q": "Cleveland voters elected Jane Campbell in 2001. What was her distinction?", "options": ["First mayor to serve only one term", "First mayor from the West Side in a century", "First mayor previously elected to county office", "First woman elected mayor of Cleveland"], "correct": 3, "reveal": "Campbell had been a state representative and a Cuyahoga County commissioner. She took office in January 2002 and served one term before losing to Frank Jackson in 2005."}, {"idx": 31, "wk": 31, "y": 2002, "cat": "tcf", "diff": "Medium", "q": "In 2002 the Cleveland Foundation started giving small grants for neighborhood projects — with a twist. Who decides which projects win?", "options": ["A committee of neighborhood residents", "City Council", "Local business leaders", "Cleveland Foundation staff"], "correct": 0, "reveal": "The program, Neighborhood Connections, puts the decision in the hands of neighbors. Grants of $500 to $5,000 have funded everything from craft classes to bringing back beekeeping — about 1,800 resident-led projects in its first 11 years."}, {"idx": 32, "wk": 32, "y": 2003, "cat": "sports", "diff": "Easy", "q": "With the number one pick in the 2003 NBA Draft, the Cavaliers selected LeBron James out of which high school?", "options": ["Shaker Heights", "Cleveland Glenville", "Garfield Heights", "Akron St. Vincent–St. Mary"], "correct": 3, "reveal": "The Cavs had won the lottery with the worst record in the league, and the hometown kid landed in their lap. That August, Cleveland also went dark in the Northeast blackout, one of the largest power failures in North American history."}, {"idx": 33, "wk": 33, "y": 2004, "cat": "politics", "diff": "Medium", "q": "What national political event did Case Western Reserve University host in October 2004?", "options": ["A presidential debate", "The vice-presidential debate between Dick Cheney and John Edwards", "The Democratic National Convention", "A Supreme Court confirmation hearing"], "correct": 1, "reveal": "Ohio was the decisive state in the 2004 election, and Cuyahoga County was the state's biggest Democratic vote bank. Campaigns treated Cleveland as a must-visit stop — a pattern that has repeated in nearly every presidential cycle since."}, {"idx": 34, "wk": 34, "y": 2005, "cat": "politics", "diff": "Medium", "q": "Frank G. Jackson was elected mayor in 2005. What record did he eventually set?", "options": ["Youngest mayor since Dennis Kucinich", "First mayor to serve five terms", "Longest-serving mayor in Cleveland history, at four terms", "First sitting mayor to be elected governor"], "correct": 2, "reveal": "Jackson, a Central neighborhood native and City Council president, served from 2006 to 2021 — 16 years. He was the first sitting council member elected mayor since 1867."}, {"idx": 35, "wk": 35, "y": 2006, "cat": "politics", "diff": "Hard", "q": "A 2006 Ohio law barred cities like Cleveland from requiring what of their municipal employees?", "options": ["Holding an Ohio driver's license", "Submitting to random drug testing", "Living inside the city limits", "Membership in a union"], "correct": 2, "reveal": "Residency requirements had kept thousands of police officers, firefighters, and city workers — and their property taxes and school enrollments — inside Cleveland. The Ohio Supreme Court upheld the law in 2009. Its effect on the city's population is still argued about today."}, {"idx": 36, "wk": 36, "y": 2007, "cat": "tcf", "diff": "Hard", "q": "The Cleveland Foundation started in 1914 with one idea and grew one gift at a time. By 2007, how much had Clevelanders built up in the savings that fund its grants every year?", "options": ["About $218 million", "About $2.18 billion", "About $21.8 billion", "About $980 million"], "correct": 1, "reveal": "That’s a long way from 1925, when the Foundation had $400,000 and could give out $15,000 in grants. Because the money is invested and only a portion is spent each year, gifts made generations ago are still helping Cleveland today."}, {"idx": 37, "wk": 37, "y": 2008, "cat": "citybuilding", "diff": "Medium", "q": "In October 2008, RTA opened the HealthLine, a bus rapid transit route running along which street?", "options": ["Detroit Avenue", "Euclid Avenue", "Carnegie Avenue", "Superior Avenue"], "correct": 1, "reveal": "The roughly $200 million project rebuilt Euclid Avenue from Public Square to University Circle with dedicated bus lanes and new streetscape. It became a national model for BRT and helped unlock a wave of MidTown and Health-Tech Corridor investment. That summer, the FBI raided county offices, opening the Cuyahoga County corruption scandal."}, {"idx": 38, "wk": 38, "y": 2009, "cat": "politics", "diff": "Hard", "q": "In November 2009, after a sweeping federal corruption investigation, Cuyahoga County voters approved a new charter. What did it replace the three county commissioners with?", "options": ["A state-appointed county manager", "An elected county executive and an 11-member county council", "A merged city-county government", "A regional authority covering five counties"], "correct": 1, "reveal": "Issue 6 was the biggest overhaul of county government in more than 150 years, passed while officials including commissioner Jimmy Dimora and auditor Frank Russo were under federal investigation. The new structure took effect in January 2011."}, {"idx": 39, "wk": 39, "y": 2010, "cat": "tcf", "diff": "Easy", "q": "In May 2010, about 10,000 people packed Cleveland’s St. Clair-Superior neighborhood for the very first edition of what event?", "options": ["A lakefront kite festival", "A citywide food truck rally", "A neighborhood jazz festival", "The Cleveland Asian Festival"], "correct": 3, "reveal": "A small $5,000 grant from the Cleveland Foundation helped launch the festival, with performances, food and shopping for Asian Pacific-American Heritage Month. It grew fast — to more than 30,000 people in 2011 and 50,000 in 2012."}, {"idx": 40, "wk": 40, "y": 2011, "cat": "tcf", "diff": "Medium", "q": "Starting in 2011, the Cleveland Foundation and partners created a $4 million fund of “microloans.” Who were these small loans mainly meant to help?", "options": ["College students paying tuition", "First-time homebuyers", "Small-business owners who couldn’t get a regular bank loan", "Large factories expanding overseas"], "correct": 2, "reveal": "A study found local entrepreneurs — especially women, immigrants and people of color — were missing out on about $38 million in small loans. Fun fact: one early borrower was former Cleveland Browns player Al “Bubba” Baker, who used his loan to start selling his signature barbecue ribs locally."}, {"idx": 41, "wk": 41, "y": 2012, "cat": "citybuilding", "diff": "Medium", "q": "In May 2012, Ohio's first casino opened in downtown Cleveland inside which landmark building?", "options": ["Terminal Tower", "The Higbee Building on Public Square", "The Arcade", "Public Auditorium"], "correct": 1, "reveal": "The old Higbee's department store — the one from *A Christmas Story* — became the Horseshoe Casino, now JACK Cleveland Casino. It was the first of four casinos authorized by Ohio voters in 2009."}, {"idx": 42, "wk": 42, "y": 2013, "cat": "citybuilding", "diff": "Medium", "q": "In June 2013, who took over day-to-day management of Cleveland's lakefront parks, including Edgewater, Euclid Beach, Villa Angela, and Gordon Park?", "options": ["The Cleveland-Cuyahoga County Port Authority", "The City of Cleveland's parks department", "Cleveland Metroparks", "The Ohio Department of Natural Resources"], "correct": 2, "reveal": "The state had run them since 1978 and had deferred millions in maintenance. Cleveland kept ownership; the Metroparks took a 99-year lease at a dollar a year. Within a few years Edgewater had a new beach house, a playground, and a summer concert series."}, {"idx": 43, "wk": 43, "y": 2014, "cat": "sports", "diff": "Medium", "q": "In July 2014, LeBron James announced his return to Cleveland in a first-person essay published where?", "options": ["The Players' Tribune", "Sports Illustrated", "On his own Instagram account", "The Plain Dealer"], "correct": 1, "reveal": "The essay, titled “I'm Coming Home,” framed the return as a commitment to Northeast Ohio. 2014 was a heavy year for the city: Cleveland hosted Gay Games 9 in August, and in November a Cleveland police officer shot and killed 12-year-old Tamir Rice at Cudell Recreation Center."}, {"idx": 44, "wk": 44, "y": 2015, "cat": "equity", "diff": "Medium", "q": "In 2015 the City of Cleveland entered a federal consent decree with the U.S. Department of Justice. What did it cover?", "options": ["Airport contracting practices", "The school district", "Reform of the Cleveland Division of Police", "Sewer overflows into Lake Erie"], "correct": 2, "reveal": "The Justice Department had found a pattern and practice of excessive force. The decree mandated new use-of-force policies, crisis intervention training, and civilian oversight, following years of organizing after the killing of Tamir Rice in 2014."}, {"idx": 45, "wk": 45, "y": 2016, "cat": "sports", "diff": "Easy", "q": "The Cavaliers won the 2016 NBA Finals after trailing the Golden State Warriors 3–1. Whose chase-down rejection in Game 7 is known in Cleveland simply as “The Block”?", "options": ["LeBron James", "Tristan Thompson", "Kevin Love", "Iman Shumpert"], "correct": 0, "reveal": "Golden State had won an NBA-record 73 games. No team had ever come back from 3–1 in the Finals. The win ended a 52-year championship drought for Cleveland's major pro teams, and an estimated 1.3 million people turned out for the parade."}, {"idx": 46, "wk": 46, "y": 2017, "cat": "sports", "diff": "Medium", "q": "In late summer 2017 the Indians set an American League record with how many consecutive wins?", "options": ["18", "26", "20", "22"], "correct": 3, "reveal": "The streak ran from late August into mid-September and captured national attention. Cleveland won the AL Central by a wide margin — then lost the division series to the Yankees after going up 2–0."}, {"idx": 47, "wk": 47, "y": 2020, "cat": "politics", "diff": "Medium", "q": "In September 2020, Cleveland hosted the first presidential debate between Donald Trump and Joe Biden. At what venue?", "options": ["The Health Education Campus shared by Case Western Reserve University and the Cleveland Clinic", "Cleveland State University's Wolstein Center", "John Carroll University", "Public Auditorium"], "correct": 0, "reveal": "The debate moved to Cleveland on short notice after Notre Dame withdrew, and it was held under heavy pandemic protocols. 2020 was also the year Ohio's first COVID-19 cases were confirmed in Cuyahoga County, and the year George Floyd protests filled downtown streets."}, {"idx": 48, "wk": 48, "y": 2022, "cat": "politics", "diff": "Medium", "q": "Justin Bibb took the oath of office in January 2022. What was notable about him?", "options": ["He was the first mayor born outside Cleveland", "He had previously served as county executive", "At 34 he was the city's second-youngest mayor and its first millennial mayor", "He had spent 20 years on City Council first"], "correct": 2, "reveal": "Bibb grew up in Mount Pleasant on the southeast side and was sworn in just after midnight at the East 131st Street library branch he used as a kid. He is Cleveland's fourth African American mayor."}, {"idx": 49, "wk": 49, "y": 2023, "cat": "tcf", "diff": "Medium", "q": "In 2023, the Cleveland Foundation — the world's first community foundation — moved its headquarters out of Playhouse Square. Which neighborhood did it move to?", "options": ["University Circle", "Tremont", "MidTown", "Ohio City"], "correct": 2, "reveal": "The new building sits at East 66th and Euclid, deliberately placed as an anchor investment in MidTown and Hough rather than downtown. It was the foundation's first move out of the central business district in more than a century. Lillian Kuri was also named president and CEO that year."}, {"idx": 50, "wk": 50, "y": 2024, "cat": "other", "diff": "Easy", "q": "On April 8, 2024, Cleveland sat squarely in the path of totality for what?", "options": ["A visible aurora borealis", "A lunar eclipse", "A meteor shower", "A total solar eclipse"], "correct": 3, "reveal": "Cleveland got nearly four minutes of darkness in the middle of the afternoon, and hundreds of thousands of visitors came for it — the first total solar eclipse visible from the city in more than 200 years. Cleveland also hosted the NCAA Women's Final Four that April."}, {"idx": 51, "wk": 51, "y": 2025, "cat": "equity", "diff": "Medium", "q": "CentroVilla25 opened on West 25th Street in the Clark-Fulton neighborhood in spring 2025. What is it?", "options": ["A soccer stadium", "A Latino marketplace, food hall, and small-business incubator", "A performing arts venue", "A regional transit center"], "correct": 1, "reveal": "The roughly $12 million adaptive reuse of a vacant warehouse was led by the Northeast Ohio Hispanic Center for Economic Development and was decades in the making. It gives Cleveland's fastest-growing community a permanent commercial and cultural anchor."}];
