var NF_POSTS=[{"name":"Maria S.","initials":"MS","type":"why","likes":14,"body":"My grandmother came to Cleveland with nothing and this city gave her a chance. Giving back through my fund is how I say thank you."},{"name":"Cleveland Foundation","initials":"CF","type":"news","likes":32,"body":"This week’s Local Legend: Frederick Goff, the banker who founded the world’s first community foundation right here in Cleveland in 1914."},{"name":"James T.","initials":"JT","type":"why","likes":9,"body":"I volunteer at the West Side Market food drive every month. Watching neighbors help neighbors is why I keep showing up."},{"name":"Cleveland Foundation","initials":"CF","type":"news","likes":21,"body":"New year, new question — test your knowledge of when major events happened across our city on the Cleveland History Quiz."},{"name":"Priya K.","initials":"PK","type":"why","likes":18,"body":"Cleveland gave my parents a home when they had nowhere else to go. Every gift I make is a small way of returning the favor."}];
